// Rail links chosen by which passes the user holds. Every URL here is a
// fixed, known page; nothing is generated by the AI. If a booking site
// changes, fix it here once.

import type { TransitPass } from '@/lib/profile/ProfileContext';
import type { BookingLink, PlaceRef } from '@/lib/trips/types';

/** Known exchange hubs and the station trips leave from. Anything else is used by name only. */
const HUBS: Record<string, PlaceRef> = {
  'lyon, france': { name: 'Lyon Part-Dieu', region: 'Rhône, France', lat: 45.7606, lng: 4.8593 },
  'vancouver, bc': { name: 'Vancouver Pacific Central', region: 'British Columbia, Canada', lat: 49.2737, lng: -123.0979 },
};

export function resolveBase(baseLocation: string): PlaceRef {
  const known = HUBS[baseLocation.trim().toLowerCase()];
  if (known) return known;
  const [name, ...rest] = baseLocation.split(',');
  return { name: name.trim(), region: rest.join(',').trim() };
}

/**
 * SNCF Connect's search page. SNCF doesn't publish a deep-link format that
 * pre-fills stations or a discount card, so this is the plain entry point.
 * Unverified query parameters would fail silently and show full fares, so
 * there are none. The card is named in the link label instead, so the user
 * knows to add it at checkout. If SNCF documents a format, add it here.
 */
export const SNCF_CONNECT_URL = 'https://www.sncf-connect.com/';
export const EURAIL_URL = 'https://www.eurail.com/';

export function railBookingLinks(passes: readonly TransitPass[]): BookingLink[] {
  const links: BookingLink[] = [];
  if (passes.includes('SNCF_AVANTAGE_JEUNE')) {
    links.push({ label: 'SNCF Connect: add your Carte Avantage Jeune at checkout', url: SNCF_CONNECT_URL, kind: 'transport' });
  } else {
    links.push({ label: 'SNCF Connect', url: SNCF_CONNECT_URL, kind: 'transport' });
  }
  if (passes.includes('EURAIL')) {
    // Pass holders still need paid seat reservations on most TGV and high-speed trains.
    links.push({ label: 'Eurail: check if this train needs a seat reservation', url: EURAIL_URL, kind: 'transport' });
  }
  return links;
}
